exercises.solutionCode:
const numbers = [1, 2, 3, 4, 5, 6, 7];

const oddSquares = numbers.filter((n) => n % 2 === 1).map((n) => n * n);
const sum = oddSquares.reduce((total, n) => total + n, 0);

console.log(oddSquares.join(","));
console.log(sum);

